namespace app\controller\admin;

use app\middleware\AdminAuth;
use app\model\Product as ProductModel;
use app\service\AdminOperationLogService;
use think\facade\Db;
use think\facade\Log;
class Product extends \app\BaseController
{
    // AdminAuth 非全局中间件，必须显式声明；缺失 = 新增 admin 路由绕过鉴权（P0）。
    protected array $middleware = [AdminAuth::class];

    public function product_post(string $action)    {        $post_info = $this->request->post();        switch ($action) {            case 'add_modify':                $productType = (int)($post_info['type'] ?? 0);                if (!$this->authorize('admin.product.manage')) return $this->directDenyAdminPermission('admin.product.manage');                if(empty($post_info['name'])){                    return show(500, 'error', '请输入产品名称');                }                if(empty($post_info['describe'])){                    return show(500, 'error', '请输入产品描述');                }                if($post_info['type'] == 1){                    if(empty($post_info['image'])){                        return show(500, 'error', '请上传产品图标');                    }                    if(empty($post_info['mini_recharge_amount'])){                        return show(500, 'error', '请输入最低充值金额');                    }                }else{                    if(empty($post_info['quiry_price'])){                        return show(500, 'error', '请输入查询价格');                    }                }                Db::startTrans();                try {                    $Product_info = ProductModel::find($post_info['id']??'');                    if($Product_info){                        $Product_info->name = $post_info['name'];                        $Product_info->home_name = $post_info['name'];                        $Product_info->describe = $post_info['describe'];                        $Product_info->tutorial_content = $post_info['tutorial_content']??null;                        $Product_info->image = $post_info['image']??null;                        $Product_info->mini_recharge_amount = $post_info['mini_recharge_amount']??null;                        $Product_info->kickback_rtion_1 = $post_info['kickback_rtion_1']??null;                        $Product_info->kickback_rtion_2 = $post_info['kickback_rtion_2']??null;                        $Product_info->kickback_rtion_3 = $post_info['kickback_rtion_3']??null;                        $Product_info->kickback_rtion_4 = $post_info['kickback_rtion_4']??null;                        $Product_info->kickback_rtion_5 = $post_info['kickback_rtion_5']??null;                        $Product_info->kickback_rtion_6 = $post_info['kickback_rtion_6']??null;                        $Product_info->kickback_rtion_7 = $post_info['kickback_rtion_7']??null;                        $Product_info->kickback_rtion_8 = $post_info['kickback_rtion_8']??null;                        $Product_info->kickback_rtion_9 = $post_info['kickback_rtion_9']??null;                        $Product_info->kickback_rtion_10 = $post_info['kickback_rtion_10']??null;                        $Product_info->order_info = $post_info['order_info']??null;                        $Product_info->par_value = $post_info['par_value']??null;                        $Product_info->discount = $post_info['discount']??null;                        $Product_info->quiry_price = $post_info['quiry_price']??null;                        $Product_info->batch_status = $post_info['batch_status']??null;                        $Product_info->product_type = $post_info['product_type']??null;                        $saveRes = $Product_info->save();                        if ($saveRes === false) {                            throw new \Exception('商品保存失败');                        }                        Db::name('substation_product_tier_price')->where('product_id', (int)$Product_info->id)->delete();                        Db::commit();                        return show(200, 'success', '修改成功');                    }                    ProductModel::create([                        'type' => $post_info['type'],                        'name' => $post_info['name'],                        'describe' => $post_info['describe'],                        'tutorial_content' => $post_info['tutorial_content']??null,                        'image' => $post_info['image']??null,                        'mini_recharge_amount' => $post_info['mini_recharge_amount']??null,                        'kickback_rtion_1' => $post_info['kickback_rtion_1']??null,                        'kickback_rtion_2' => $post_info['kickback_rtion_2']??null,                        'kickback_rtion_3' => $post_info['kickback_rtion_3']??null,                        'kickback_rtion_4' => $post_info['kickback_rtion_4']??null,                        'kickback_rtion_5' => $post_info['kickback_rtion_5']??null,                        'kickback_rtion_6' => $post_info['kickback_rtion_6']??null,                        'kickback_rtion_7' => $post_info['kickback_rtion_7']??null,                        'kickback_rtion_8' => $post_info['kickback_rtion_8']??null,                        'kickback_rtion_9' => $post_info['kickback_rtion_9']??null,                        'kickback_rtion_10' => $post_info['kickback_rtion_10']??null,                        'order_info' => $post_info['order_info']??null,                        'par_value' => $post_info['par_value']??null,                        'discount' => $post_info['discount']??null,                        'quiry_price' => $post_info['quiry_price']??null,                        'batch_status' => $post_info['batch_status']??null,                        'product_type' => $post_info['product_type'] ?? null,                    ]);                    Db::commit();                    return show(200, 'success', '添加成功');                } catch (\Throwable $e) {                    Db::rollback();                    Log::error('product_post add_modify error: ' . $e->getMessage(), [                        'id' => (int)($post_info['id'] ?? 0),                        'action' => 'add_modify',                    ]);                    return show(500, 'error', !empty($post_info['id']) ? '修改失败' : '添加失败');                }            case 'info':                $res = ProductModel::find($post_info['id']);                                if($res['type'] == 1){                    $order_info_html = '';                    foreach($res['order_info'] as $key => $vo_a) {                        $selected_1 = $selected_2 = $selected_3 = $selected_4 = '';                        if($vo_a['type'] == 1){                            $selected_1 = 'selected';                        }elseif($vo_a['type'] == 2){                            $selected_2 = 'selected';                        }elseif($vo_a['type'] == 3){                            $selected_3 = 'selected';                        }elseif($vo_a['type'] == 4){                            $selected_4 = 'selected';                        }                        $order_info_html .= '                        <div data-repeater-item order_info_html>                            <div class="form-group row mb-3">                                <div class="col-md-10">                                    <div class="input-group">                                        <span class="input-group-text">类型：</span>                                        <select class="form-select" id="type" data-placeholder="请选择类型">                                            <option value="1" '.$selected_1.'>输入框</option>                                            <option value="2" '.$selected_2.'>地区选择（市）</option>                                            <option value="3" '.$selected_3.'>地区选择（区）</option>                                            <option value="4" '.$selected_4.'>图片上传</option>                                        </select>                                        <span class="input-group-text">排序：</span>                                        <input type="text" class="form-control" id="sort" placeholder="请输入排序" value="'.$vo_a['sort'].'"/>                                    </div>                                    <div class="input-group">                                        <span class="input-group-text">名称：</span>                                        <input type="text" class="form-control" id="name" placeholder="请输入名称" value="'.$vo_a['name'].'"/>                                    </div>                                </div>                                <div class="col-md-2">                                    <a href="javascript:;" data-repeater-delete class="btn btn-light-danger">                                        <i class="ki-duotone ki-trash fs-5"><span class="path1"></span><span class="path2"></span><span class="path3"></span><span class="path4"></span><span class="path5"></span></i>                                    </a>                                </div>                            </div>                        </div>';                    }                    $res['order_info_html'] = $order_info_html;                    $par_value_html = '';                    foreach($res['par_value'] as $key => $vo_b) {                        $name = $vo_b['name']??'';                        $par_value_html .= '                        <div data-repeater-item>                            <div class="form-group row mb-3">                                <div class="col-md-10">                                    <div class="input-group">                                        <span class="input-group-text">名称：</span>                                        <input type="text" class="form-control" id="name" placeholder="请输入名称" value="'.$name.'"/>                                        <span class="input-group-text">面值：</span>                                        <input type="text" class="form-control" id="value" placeholder="请输入面值" value="'.$vo_b['value'].'"/>                                    </div>                                </div>                                <div class="col-md-2">                                    <a href="javascript:;" data-repeater-delete class="btn btn-light-danger">                                        <i class="ki-duotone ki-trash fs-5"><span class="path1"></span><span class="path2"></span><span class="path3"></span><span class="path4"></span><span class="path5"></span></i>                                    </a>                                </div>                            </div>                        </div>';                    }                    $res['par_value_html'] = $par_value_html;                                        $discount_html = '';                    foreach($res['discount'] as $key => $vo_c) {                        $discount_html .= '                        <div data-repeater-item>                            <div class="form-group row mb-3">                                <div class="col-md-10">                                    <div class="input-group">                                        <input type="text" id="mini_amount" class="form-control form-control-" placeholder="请输入金额" value="'.$vo_c['mini_amount'].'">                                        <span class="input-group-text">~</span>                                        <input type="text" id="maxi_amount" class="form-control form-control-" placeholder="请输入金额" value="'.$vo_c['maxi_amount'].'">                                        <span class="input-group-text">折扣</span>                                        <input type="text" id="discounts" class="form-control form-control-" placeholder="请输入折扣" value="'.$vo_c['discount'].'">                                    </div>                                </div>                                <div class="col-md-2">                                    <a href="javascript:;" data-repeater-delete class="btn btn-light-danger">                                        <i class="ki-duotone ki-trash fs-5"><span class="path1"></span><span class="path2"></span><span class="path3"></span><span class="path4"></span><span class="path5"></span></i>                                    </a>                                </div>                            </div>                        </div>';                    }                    $res['discount_html'] = $discount_html;                }                return show(200, 'success', '获取信息成功', (array)$res->getData());                            case 'status_switch':                $id = (int)($post_info['id'] ?? 0);                if ($id <= 0) {                    return show(500, 'error', '参数错误');                }                $res = ProductModel::find($id);                if (!$res) {                    return show(500, 'error', '产品不存在');                }                $prodType = (int)$res['type'];                if (!$this->authorize('admin.product.manage')) return $this->directDenyAdminPermission('admin.product.manage');                $oldStatus = (int)$res['status'];                $newStatus = $oldStatus === ProductModel::STATUS_DISABLED ? ProductModel::STATUS_ENABLED : ProductModel::STATUS_DISABLED;                $res->status = $newStatus;                $res->save();                $this->writeAdminLog('切换产品状态', '产品管理', '产品ID：' . $id . '，产品名称：' . (string)$res['name'] . '，类型：' . $prodType . '，状态：' . $oldStatus . ' -> ' . $newStatus);                return show(200, 'success', '状态更新成功');            case 'sort':                $id = (int)($post_info['id'] ?? 0);                if ($id <= 0) {                    return show(500, 'error', '参数错误');                }                $res = ProductModel::find($id);                if (!$res) {                    return show(500, 'error', '产品不存在');                }                $prodType = (int)$res['type'];                if (!$this->authorize('admin.product.manage')) return $this->directDenyAdminPermission('admin.product.manage');                $oldSort = (int)$res['sort'];                $newSort = (int)($post_info['sort'] ?? 0);                $res->sort = $newSort;                $res->save();                $this->writeAdminLog('修改产品排序', '产品管理', '产品ID：' . $id . '，产品名称：' . (string)$res['name'] . '，排序：' . $oldSort . ' -> ' . $newSort);                return show(200, 'success', '更新成功');            case 'del':                $id = (int)($post_info['id'] ?? 0);                if ($id <= 0) {                    return show(500, 'error', '参数错误');                }                $res = ProductModel::find($id);                if (!$res) {                    return show(500, 'error', '产品不存在');                }                $prodType = (int)$res['type'];                if (!$this->authorize('admin.product.delete')) return $this->directDenyAdminPermission('admin.product.delete');                $productName = (string)$res['name'];                ProductModel::destroy($id);                $this->writeAdminLog('删除产品', '产品管理', '产品ID：' . $id . '，产品名称：' . $productName . '，类型：' . $prodType);                return show(200, 'success', '删除成功');            case 'dels':                $idsRaw = $post_info['ids'] ?? '';                if (is_array($idsRaw)) {                    $ids = array_filter(array_map('intval', $idsRaw), static fn($v) => $v > 0);                } else {                    $ids = array_filter(array_map('intval', explode(',', (string)$idsRaw)), static fn($v) => $v > 0);                }                if (empty($ids)) {                    return show(500, 'error', '参数错误');                }                $products = ProductModel::where('id', 'in', $ids)->select();                $deletedCount = 0;                $productNames = [];                foreach ($products as $vo) {                    $prodType = (int)$vo['type'];                    if (!$this->authorize('admin.product.delete')) return $this->directDenyAdminPermission('admin.product.delete');                    $productNames[] = (string)$vo['name'];                    ProductModel::destroy($vo['id']);                    $deletedCount++;                }                $this->writeAdminLog('批量删除产品', '产品管理', '删除数量：' . $deletedCount . '，产品ID：' . implode(',', $ids) . '，产品名称：' . implode(',', $productNames));                return show(200, 'success', '删除成功');                            default:                return show(500, 'error', '你不对劲');        }    }
    /**
     * 操作日志统一入口（B06 迁移到 AdminOperationLogService::record()）
     */
    private function writeAdminLog(string $action, string $module, string $content, array $options = []): void
    {
        app(AdminOperationLogService::class)->record($action, $module, $content, array_merge([
            'admin' => $this->currentAdminIdentity(),
        ], $options));
    }
}
